import { sql } from 'drizzle-orm';
import {
  bigint,
  boolean,
  check,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
} from 'drizzle-orm/pg-core';

// Amounts are integer micro-USD (see @kiqro/core money.ts). IDs are prefixed ULIDs generated by the app.
const micros = (name: string) => bigint(name, { mode: 'bigint' });
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

export const orgType = pgEnum('org_type', ['advertiser', 'publisher', 'internal']);
export const orgStatus = pgEnum('org_status', ['pending', 'active', 'suspended']);
export const platform = pgEnum('platform', ['android', 'ios', 'web']);
export const campaignStatus = pgEnum('campaign_status', ['draft', 'in_review', 'active', 'paused', 'completed', 'archived']);
export const placementStatus = pgEnum('placement_status', ['active', 'paused']);
export const conversionStatus = pgEnum('conversion_status', ['approved', 'held', 'rejected', 'reversed']);
export const ledgerAccountKind = pgEnum('ledger_account_kind', [
  'advertiser_balance', // funds an advertiser has prepaid and not yet spent
  'publisher_payable', // what Kiqro owes a publisher; may go negative after chargebacks
  'kiqro_revenue',
  'external_cash', // counterpart for money entering or leaving the system (Stripe, bank)
]);
export const outboxStatus = pgEnum('outbox_status', ['pending', 'sent', 'failed']);

export const organizations = pgTable('organizations', {
  id: text('id').primaryKey(),
  type: orgType('type').notNull(),
  name: text('name').notNull(),
  country: text('country'),
  status: orgStatus('status').notNull().default('pending'),
  /** Legal entity that invoices this organization: "kiqro_inc" until the Finnish Oy exists. */
  billingEntity: text('billing_entity').notNull().default('kiqro_inc'),
  invoiceCurrency: text('invoice_currency').notNull().default('USD'),
  /** Identifies the advertiser in MMP postback URLs: /v1/mmp/{postback_key}. */
  postbackKey: text('postback_key').unique(),
  postbackSecret: text('postback_secret'),
  /** Days after a conversion during which the advertiser may reverse it. */
  reversalWindowDays: integer('reversal_window_days').notNull().default(30),
  /** Advertisers get an e-mail when their balance falls below this (micro-USD). */
  lowBalanceThreshold: micros('low_balance_threshold').notNull().default(sql`100000000`), // $100
  lowBalanceAlertedAt: timestamp('low_balance_alerted_at', { withTimezone: true }),
  /**
   * Credit line (micro-USD) granted by Kiqro finance: the balance may go this far below zero.
   * 0 = prepaid only. Debt is invoiced monthly and due paymentTermsDays after the invoice.
   */
  creditLimit: micros('credit_limit').notNull().default(sql`0`),
  paymentTermsDays: integer('payment_terms_days').notNull().default(30),
  /** Invoice recipient details, kept up to date by the advertiser in the panel. */
  legalName: text('legal_name'),
  billingAddress: text('billing_address'),
  /** EU VAT number (needed for the reverse charge) or other tax ID. */
  vatId: text('vat_id'),
  billingEmail: text('billing_email'),
  createdAt: createdAt(),
});

export const products = pgTable('products', {
  id: text('id').primaryKey(),
  orgId: text('org_id').notNull().references(() => organizations.id),
  platform: platform('platform').notNull(),
  /** Play package name, App Store id or web domain. */
  storeId: text('store_id').notNull(),
  name: text('name').notNull(),
  iconUrl: text('icon_url'),
  /** Wide banner (about 2:1) shown on offerwall cards; the icon is used when it is missing. */
  coverUrl: text('cover_url'),
  mmp: text('mmp'),
  createdAt: createdAt(),
});

export const campaigns = pgTable(
  'campaigns',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id').notNull().references(() => organizations.id),
    productId: text('product_id').notNull().references(() => products.id),
    name: text('name').notNull(),
    status: campaignStatus('status').notNull().default('draft'),
    /** Advertiser/MMP click URL with macros such as {click_id}. */
    trackingUrl: text('tracking_url').notNull(),
    countries: text('countries').array().notNull(),
    totalBudget: micros('total_budget').notNull(),
    dailyBudget: micros('daily_budget'),
    startAt: timestamp('start_at', { withTimezone: true }),
    endAt: timestamp('end_at', { withTimezone: true }),
    attributionWindowDays: integer('attribution_window_days').notNull().default(7),
    /** Installs faster than this after the click are treated as injected and rejected. */
    ctitMinSeconds: integer('ctit_min_seconds').notNull().default(10),
    /** Who created it: an admin user id or an advertiser user id (self-serve). */
    createdBy: text('created_by'),
    submittedAt: timestamp('submitted_at', { withTimezone: true }),
    /** Kiqro's note when a submitted campaign is sent back for changes. */
    reviewNote: text('review_note'),
    reviewedAt: timestamp('reviewed_at', { withTimezone: true }),
    title: jsonb('title').$type<Record<string, string>>().notNull(),
    description: jsonb('description').$type<Record<string, string>>().notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [index('campaigns_status_idx').on(t.status)],
);

export const campaignTasks = pgTable(
  'campaign_tasks',
  {
    id: text('id').primaryKey(),
    campaignId: text('campaign_id').notNull().references(() => campaigns.id),
    seq: integer('seq').notNull(),
    /** Event name exactly as the MMP sends it; "install" for the install step. */
    mmpEventName: text('mmp_event_name').notNull(),
    /** Days after the install within which this event must arrive to be paid. */
    timeLimitDays: integer('time_limit_days').notNull(),
    displayName: jsonb('display_name').$type<Record<string, string>>().notNull(),
  },
  (t) => [uniqueIndex('campaign_tasks_event_uq').on(t.campaignId, t.mmpEventName), uniqueIndex('campaign_tasks_seq_uq').on(t.campaignId, t.seq)],
);

export const taskPayouts = pgTable(
  'task_payouts',
  {
    id: text('id').primaryKey(),
    taskId: text('task_id').notNull().references(() => campaignTasks.id),
    /** ISO country code, or "*" for the default price. */
    country: text('country').notNull(),
    price: micros('price').notNull(),
  },
  (t) => [uniqueIndex('task_payouts_uq').on(t.taskId, t.country), check('task_payouts_price_positive', sql`${t.price} > 0`)],
);

export const placements = pgTable('placements', {
  id: text('id').primaryKey(),
  publisherOrgId: text('publisher_org_id').notNull().references(() => organizations.id),
  name: text('name').notNull(),
  appKey: text('app_key').notNull().unique(),
  secret: text('secret').notNull(),
  status: placementStatus('status').notNull().default('active'),
  currencyName: text('currency_name').notNull(),
  /** Set by the publisher: how many points one USD of publisher payout is worth. */
  pointsPerUsd: numeric('points_per_usd', { precision: 18, scale: 6 }).notNull(),
  /** Set by Kiqro admin per publisher/placement: publisher share of the advertiser price. */
  revshareBps: integer('revshare_bps').notNull(),
  /** Publisher server URL with macros such as {user_id} {amount} {status} {signature}. */
  postbackUrl: text('postback_url'),
  /** Hosted offerwall branding, set by the publisher: accent colour (#rrggbb), logo and heading. */
  brandColor: text('brand_color'),
  logoUrl: text('logo_url'),
  wallTitle: text('wall_title'),
  createdAt: createdAt(),
});

export const clicks = pgTable(
  'clicks',
  {
    id: text('id').primaryKey(),
    campaignId: text('campaign_id').notNull().references(() => campaigns.id),
    placementId: text('placement_id').notNull().references(() => placements.id),
    publisherUserId: text('publisher_user_id').notNull(),
    country: text('country'),
    ip: text('ip'),
    userAgent: text('user_agent'),
    subIds: jsonb('sub_ids').$type<Record<string, string>>().notNull().default({}),
    /** IP intelligence verdict at click time (VPN/proxy/datacenter flags, provider risk score). */
    ipRisk: jsonb('ip_risk').$type<IpRisk>(),
    /** Optional 0–100 risk score the publisher passes for its user (Kiqro's own fraud score). */
    publisherRisk: integer('publisher_risk'),
    createdAt: createdAt(),
  },
  (t) => [index('clicks_user_idx').on(t.placementId, t.publisherUserId, t.campaignId), index('clicks_ip_idx').on(t.ip, t.createdAt)],
);

export interface IpRisk {
  source: string;
  country: string | null;
  vpn: boolean;
  proxy: boolean;
  tor: boolean;
  datacenter: boolean;
  /** 0 (clean) – 100 (certainly abusive), as reported by the provider. */
  score: number;
}

/** Every postback exactly as received, written before any processing; evidence for disputes. */
export const postbacksRaw = pgTable('postbacks_raw', {
  id: text('id').primaryKey(),
  source: text('source').notNull(),
  url: text('url').notNull(),
  ip: text('ip'),
  outcome: text('outcome'),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
});

export const conversions = pgTable(
  'conversions',
  {
    id: text('id').primaryKey(),
    clickId: text('click_id').notNull().references(() => clicks.id),
    taskId: text('task_id').notNull().references(() => campaignTasks.id),
    campaignId: text('campaign_id').notNull().references(() => campaigns.id),
    placementId: text('placement_id').notNull().references(() => placements.id),
    publisherUserId: text('publisher_user_id').notNull(),
    status: conversionStatus('status').notNull(),
    reasons: text('reasons').array().notNull().default([]),
    advertiserPrice: micros('advertiser_price').notNull(),
    publisherPayout: micros('publisher_payout').notNull(),
    userRewardPoints: bigint('user_reward_points', { mode: 'bigint' }).notNull(),
    eventAt: timestamp('event_at', { withTimezone: true }).notNull(),
    postbackRawId: text('postback_raw_id').references(() => postbacksRaw.id),
    createdAt: createdAt(),
    reversedAt: timestamp('reversed_at', { withTimezone: true }),
    reversalReason: text('reversal_reason'),
  },
  (t) => [
    uniqueIndex('conversions_click_task_uq').on(t.clickId, t.taskId),
    index('conversions_user_task_idx').on(t.placementId, t.publisherUserId, t.taskId),
    index('conversions_campaign_idx').on(t.campaignId, t.createdAt),
  ],
);

export const ledgerAccounts = pgTable(
  'ledger_accounts',
  {
    id: text('id').primaryKey(),
    kind: ledgerAccountKind('kind').notNull(),
    /** Organization owning the account; null for system accounts (revenue, cash). */
    orgId: text('org_id').references(() => organizations.id),
    currency: text('currency').notNull().default('USD'),
  },
  // NULLS NOT DISTINCT so system accounts (org_id null) also stay unique per kind and currency.
  (t) => [unique('ledger_accounts_uq').on(t.kind, t.orgId, t.currency).nullsNotDistinct()],
);

export const ledgerTransactions = pgTable('ledger_transactions', {
  id: text('id').primaryKey(),
  type: text('type').notNull(),
  refType: text('ref_type'),
  refId: text('ref_id'),
  memo: text('memo'),
  createdAt: createdAt(),
});

/** Append-only. Entries of one transaction sum to zero; balances are always derived from entries. */
export const ledgerEntries = pgTable(
  'ledger_entries',
  {
    id: text('id').primaryKey(),
    transactionId: text('transaction_id').notNull().references(() => ledgerTransactions.id),
    accountId: text('account_id').notNull().references(() => ledgerAccounts.id),
    amount: micros('amount').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('ledger_entries_account_idx').on(t.accountId)],
);

export const adminRole = pgEnum('admin_role', ['admin', 'operator', 'finance', 'viewer']);

/** Kiqro staff who use the admin panel. Passwords are scrypt hashes ("scrypt$N$salt$hash"). */
export const adminUsers = pgTable('admin_users', {
  id: text('id').primaryKey(),
  email: text('email').notNull().unique(),
  name: text('name').notNull(),
  role: adminRole('role').notNull().default('operator'),
  passwordHash: text('password_hash').notNull(),
  /** Base32 TOTP secret; set during enrollment, active once totpEnabledAt is set. */
  totpSecret: text('totp_secret'),
  totpEnabledAt: timestamp('totp_enabled_at', { withTimezone: true }),
  disabledAt: timestamp('disabled_at', { withTimezone: true }),
  lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
  createdAt: createdAt(),
});

/** Only a SHA-256 of the session token is stored, so a database leak does not leak sessions. */
export const adminSessions = pgTable('admin_sessions', {
  tokenHash: text('token_hash').primaryKey(),
  adminUserId: text('admin_user_id').notNull().references(() => adminUsers.id),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  ip: text('ip'),
  createdAt: createdAt(),
});

/** Team role in the advertiser panel: admins also manage the team. */
export const advertiserRole = pgEnum('advertiser_role', ['admin', 'member']);

/** People at an advertiser who can sign in to the advertiser panel (kiqronetwork.com/app). */
export const advertiserUsers = pgTable('advertiser_users', {
  id: text('id').primaryKey(),
  orgId: text('org_id').notNull().references(() => organizations.id),
  email: text('email').notNull().unique(),
  name: text('name').notNull(),
  passwordHash: text('password_hash').notNull(),
  locale: text('locale').notNull().default('en'),
  role: advertiserRole('role').notNull().default('admin'),
  /** Teammate who invited this user (null when Kiqro staff created the login). */
  invitedBy: text('invited_by'),
  /** Optional two-factor authentication (TOTP), set up by the user in Account. */
  totpSecret: text('totp_secret'),
  totpEnabledAt: timestamp('totp_enabled_at', { withTimezone: true }),
  /** Version of the Advertiser Terms this user accepted, with time and IP (proof of acceptance). */
  termsAcceptedVersion: text('terms_accepted_version'),
  termsAcceptedAt: timestamp('terms_accepted_at', { withTimezone: true }),
  termsAcceptedIp: text('terms_accepted_ip'),
  disabledAt: timestamp('disabled_at', { withTimezone: true }),
  lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
  createdAt: createdAt(),
});

export const advertiserSessions = pgTable('advertiser_sessions', {
  tokenHash: text('token_hash').primaryKey(),
  advertiserUserId: text('advertiser_user_id').notNull().references(() => advertiserUsers.id),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  ip: text('ip'),
  createdAt: createdAt(),
});

export const advertiserLoginAttempts = pgTable(
  'advertiser_login_attempts',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(),
    ip: text('ip'),
    success: boolean('success').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('advertiser_login_attempts_email_idx').on(t.email, t.createdAt), index('advertiser_login_attempts_ip_idx').on(t.ip, t.createdAt)],
);

export const tokenPurpose = pgEnum('token_purpose', ['invite', 'reset']);

/** Single-use links for setting a password (invitation) or resetting it. Only a hash is stored. */
export const advertiserTokens = pgTable(
  'advertiser_tokens',
  {
    tokenHash: text('token_hash').primaryKey(),
    advertiserUserId: text('advertiser_user_id').notNull().references(() => advertiserUsers.id),
    purpose: tokenPurpose('purpose').notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    usedAt: timestamp('used_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('advertiser_tokens_user_idx').on(t.advertiserUserId, t.createdAt)],
);

/** Outgoing e-mail, delivered and retried by the worker (same pattern as publisher postbacks). */
export const emailMessages = pgTable(
  'email_messages',
  {
    id: text('id').primaryKey(),
    to: text('to').notNull(),
    template: text('template').notNull(),
    subject: text('subject').notNull(),
    html: text('html').notNull(),
    text: text('text').notNull(),
    status: outboxStatus('status').notNull().default('pending'),
    attempts: integer('attempts').notNull().default(0),
    nextAttemptAt: timestamp('next_attempt_at', { withTimezone: true }).notNull().defaultNow(),
    lastError: text('last_error'),
    providerMessageId: text('provider_message_id'),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('email_messages_due_idx').on(t.status, t.nextAttemptAt)],
);

export const leadStatus = pgEnum('lead_status', ['new', 'contacted', 'qualified', 'won', 'lost']);

/** Demo requests from the marketing site. */
export const leads = pgTable(
  'leads',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    email: text('email').notNull(),
    company: text('company').notNull(),
    website: text('website'),
    vertical: text('vertical'),
    monthlyBudget: text('monthly_budget'),
    message: text('message'),
    locale: text('locale').notNull(),
    ip: text('ip'),
    status: leadStatus('status').notNull().default('new'),
    createdAt: createdAt(),
  },
  (t) => [index('leads_created_idx').on(t.createdAt), index('leads_ip_idx').on(t.ip, t.createdAt)],
);

/** Admin login attempts, used to lock out password guessing. */
export const adminLoginAttempts = pgTable(
  'admin_login_attempts',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(),
    ip: text('ip'),
    success: boolean('success').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('admin_login_attempts_email_idx').on(t.email, t.createdAt), index('admin_login_attempts_ip_idx').on(t.ip, t.createdAt)],
);

/** Every admin action that changes data. Append-only. */
export const auditLog = pgTable(
  'audit_log',
  {
    id: text('id').primaryKey(),
    adminUserId: text('admin_user_id').references(() => adminUsers.id),
    action: text('action').notNull(),
    entityType: text('entity_type').notNull(),
    entityId: text('entity_id').notNull(),
    details: jsonb('details').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [index('audit_log_entity_idx').on(t.entityType, t.entityId)],
);

/** Publisher postbacks waiting to be delivered, retried with backoff by the worker. */
export const publisherPostbacks = pgTable(
  'publisher_postbacks',
  {
    id: text('id').primaryKey(),
    conversionId: text('conversion_id').notNull().references(() => conversions.id),
    kind: text('kind').notNull(), // credit | reversal
    url: text('url').notNull(),
    status: outboxStatus('status').notNull().default('pending'),
    attempts: integer('attempts').notNull().default(0),
    nextAttemptAt: timestamp('next_attempt_at', { withTimezone: true }).notNull().defaultNow(),
    lastError: text('last_error'),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('publisher_postbacks_due_idx').on(t.status, t.nextAttemptAt), uniqueIndex('publisher_postbacks_uq').on(t.conversionId, t.kind)],
);

export const invoiceStatus = pgEnum('invoice_status', ['open', 'paid', 'void']);

/**
 * Monthly invoices for advertisers on credit terms: the debt (negative balance) not covered by
 * earlier open invoices. Payments are applied to open invoices oldest first.
 */
export const invoices = pgTable(
  'invoices',
  {
    id: text('id').primaryKey(),
    number: text('number').notNull().unique(),
    orgId: text('org_id').notNull().references(() => organizations.id),
    billingEntity: text('billing_entity').notNull(),
    periodStart: timestamp('period_start', { withTimezone: true }).notNull(),
    periodEnd: timestamp('period_end', { withTimezone: true }).notNull(),
    /** Net campaign spend in the period, for information. */
    periodSpend: micros('period_spend').notNull(),
    amount: micros('amount').notNull(),
    amountPaid: micros('amount_paid').notNull().default(sql`0`),
    status: invoiceStatus('status').notNull().default('open'),
    issuedAt: timestamp('issued_at', { withTimezone: true }).notNull(),
    dueAt: timestamp('due_at', { withTimezone: true }).notNull(),
    paidAt: timestamp('paid_at', { withTimezone: true }),
    overdueNotifiedAt: timestamp('overdue_notified_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('invoices_org_period_uq').on(t.orgId, t.periodStart), index('invoices_open_idx').on(t.status, t.dueAt)],
);

export const paymentMethod = pgEnum('payment_method', ['stripe', 'bank_transfer', 'other']);
export const paymentStatus = pgEnum('payment_status', ['pending', 'succeeded', 'failed', 'expired']);

/** Money paid in by advertisers: Stripe Checkout (self-serve) or bank transfers recorded by finance. */
export const payments = pgTable(
  'payments',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id').notNull().references(() => organizations.id),
    method: paymentMethod('method').notNull(),
    status: paymentStatus('status').notNull().default('pending'),
    amount: micros('amount').notNull(),
    currency: text('currency').notNull().default('USD'),
    /** Invoice the payer meant to pay, if any (payments are still applied oldest invoice first). */
    invoiceId: text('invoice_id').references(() => invoices.id),
    stripeSessionId: text('stripe_session_id').unique(),
    stripePaymentIntentId: text('stripe_payment_intent_id'),
    /** Bank transfer reference or note. */
    reference: text('reference'),
    ledgerTransactionId: text('ledger_transaction_id').references(() => ledgerTransactions.id),
    /** Refunded through Stripe so far; already taken off the balance. */
    refundedAmount: micros('refunded_amount').notNull().default(sql`0`),
    advertiserUserId: text('advertiser_user_id').references(() => advertiserUsers.id),
    adminUserId: text('admin_user_id').references(() => adminUsers.id),
    completedAt: timestamp('completed_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('payments_org_idx').on(t.orgId, t.createdAt)],
);

export const claimStatus = pgEnum('claim_status', ['open', 'approved', 'rejected']);

/**
 * Missing-credit claims: a publisher's user says they completed a task but got no reward.
 * Filed through the publisher (Offers API), matched to the user's click, decided by the
 * advertiser (or Kiqro). Approving one creates a billable conversion.
 */
export const claims = pgTable(
  'claims',
  {
    id: text('id').primaryKey(),
    placementId: text('placement_id').notNull().references(() => placements.id),
    publisherUserId: text('publisher_user_id').notNull(),
    campaignId: text('campaign_id').notNull().references(() => campaigns.id),
    taskId: text('task_id').notNull().references(() => campaignTasks.id),
    clickId: text('click_id').notNull().references(() => clicks.id),
    status: claimStatus('status').notNull().default('open'),
    /** What the user wrote (e.g. "reached level 10 on 3 Nov"). */
    userNote: text('user_note'),
    /** Reason shown to the publisher when rejected, or a note on approval. */
    decisionNote: text('decision_note'),
    decidedByAdvertiserUserId: text('decided_by_advertiser_user_id').references(() => advertiserUsers.id),
    decidedByAdminUserId: text('decided_by_admin_user_id').references(() => adminUsers.id),
    decidedAt: timestamp('decided_at', { withTimezone: true }),
    conversionId: text('conversion_id').references(() => conversions.id),
    createdAt: createdAt(),
  },
  (t) => [index('claims_campaign_idx').on(t.campaignId, t.status, t.createdAt), index('claims_user_idx').on(t.placementId, t.publisherUserId)],
);

/**
 * Advertiser API keys. Only a SHA-256 hash is stored; the key is shown once when created.
 * A key acts as the teammate who created it and stops working if that person is removed.
 */
export const advertiserApiKeys = pgTable(
  'advertiser_api_keys',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id').notNull().references(() => organizations.id),
    name: text('name').notNull(),
    /** First characters of the key, to recognise it in the panel ("kq_live_ab12…"). */
    prefix: text('prefix').notNull(),
    keyHash: text('key_hash').notNull().unique(),
    createdBy: text('created_by').notNull().references(() => advertiserUsers.id),
    lastUsedAt: timestamp('last_used_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('advertiser_api_keys_org_idx').on(t.orgId)],
);

/** Advertiser webhook endpoints: Kiqro POSTs signed event notifications to `url`. */
export const webhookEndpoints = pgTable(
  'webhook_endpoints',
  {
    id: text('id').primaryKey(),
    orgId: text('org_id').notNull().references(() => organizations.id),
    url: text('url').notNull(),
    /** Signing secret (whsec_…); kept readable because every delivery is signed with it. */
    secret: text('secret').notNull(),
    events: text('events').array().notNull(),
    disabledAt: timestamp('disabled_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('webhook_endpoints_org_idx').on(t.orgId)],
);

/** Webhook deliveries, retried with backoff by the worker (same lease pattern as postbacks). */
export const webhookDeliveries = pgTable(
  'webhook_deliveries',
  {
    id: text('id').primaryKey(),
    endpointId: text('endpoint_id').notNull().references(() => webhookEndpoints.id, { onDelete: 'cascade' }),
    event: text('event').notNull(),
    payload: jsonb('payload').$type<Record<string, unknown>>().notNull(),
    status: outboxStatus('status').notNull().default('pending'),
    attempts: integer('attempts').notNull().default(0),
    nextAttemptAt: timestamp('next_attempt_at', { withTimezone: true }).notNull().defaultNow(),
    lastError: text('last_error'),
    responseStatus: integer('response_status'),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('webhook_deliveries_due_idx').on(t.status, t.nextAttemptAt), index('webhook_deliveries_endpoint_idx').on(t.endpointId, t.createdAt)],
);

/**
 * In-app revenue the advertiser's MMP reports for users Kiqro brought (purchases, ad revenue),
 * in USD. Not billed: it is what ROAS reports are built from.
 */
export const revenueEvents = pgTable(
  'revenue_events',
  {
    id: text('id').primaryKey(),
    clickId: text('click_id').notNull().references(() => clicks.id),
    campaignId: text('campaign_id').notNull().references(() => campaigns.id),
    event: text('event').notNull(),
    revenue: micros('revenue').notNull(),
    /** The MMP's own event id, when sent, so a retried postback is not counted twice. */
    externalId: text('external_id'),
    eventAt: timestamp('event_at', { withTimezone: true }).notNull(),
    postbackRawId: text('postback_raw_id').references(() => postbacksRaw.id),
    createdAt: createdAt(),
  },
  (t) => [index('revenue_events_campaign_idx').on(t.campaignId, t.eventAt), uniqueIndex('revenue_events_external_uq').on(t.clickId, t.externalId)],
);
